import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

conv2d_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#define TILE_H 4
#define TILE_W 4
#define THREAD_TILE 1
#define BLOCK_H (TILE_H / THREAD_TILE)
#define BLOCK_W (TILE_W / THREAD_TILE)
#define OC_TILE 4
__global__ void conv2d_kernel_tiled(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int batch_size,
    int in_channels,
    int in_h, int in_w,
    int out_channels,
    int out_h, int out_w,
    int kernel_size,
    int stride,
    int padding,
    int in_tile_h,
    int in_tile_w)
{
    extern __shared__ float smem[];
    int tile_ow = blockIdx.x * TILE_W;
    int tile_oh = blockIdx.y * TILE_H;
    int n = blockIdx.z;
    int tx = threadIdx.x;
    int ty = threadIdx.y;
    int num_threads = BLOCK_H * BLOCK_W;
    int tid = ty * BLOCK_W + tx;
    int in_h_start = tile_oh * stride - padding;
    int in_w_start = tile_ow * stride - padding;
    int in_tile_hw = in_tile_h * in_tile_w;
    int tile_size = in_channels * in_tile_hw;
    int wsize = in_channels * kernel_size * kernel_size;
    float* wshared = smem + tile_size;
    for (int i = tid; i < tile_size; i += num_threads) {
        int ic = i / in_tile_hw;
        int rem = i % in_tile_hw;
        int ih_local = rem / in_tile_w;
        int iw_local = rem % in_tile_w;
        int ih = in_h_start + ih_local;
        int iw = in_w_start + iw_local;
        float val = 0.0f;
        if (ih >= 0 && ih < in_h && iw >= 0 && iw < in_w) {
            val = input[((n * in_channels + ic) * in_h + ih) * in_w + iw];
        }
        smem[i] = val;
    }
    __syncthreads();
    int oh_base = tile_oh + ty * THREAD_TILE;
    int ow_base = tile_ow + tx * THREAD_TILE;
    int local_h_start = ty * THREAD_TILE * stride;
    int local_w_start = tx * THREAD_TILE * stride;
    bool any_valid = (oh_base < out_h) && (ow_base < out_w);
    int ksq = kernel_size * kernel_size;
    for (int oc_base = 0; oc_base < out_channels; oc_base += OC_TILE) {
        int oc_count = min(OC_TILE, out_channels - oc_base);
        int total_w = oc_count * wsize;
        for (int i = tid; i < total_w; i += num_threads) {
            int local_oc = i / wsize;
            int w_idx = i % wsize;
            wshared[i] = weight[(oc_base + local_oc) * wsize + w_idx];
        }
        __syncthreads();
        if (any_valid) {
            float sums[OC_TILE][THREAD_TILE][THREAD_TILE];
            #pragma unroll
            for (int o = 0; o < OC_TILE; ++o) {
                float bias_val = (o < oc_count) ? bias[oc_base + o] : 0.0f;
                #pragma unroll
                for (int th = 0; th < THREAD_TILE; ++th) {
                    #pragma unroll
                    for (int tw = 0; tw < THREAD_TILE; ++tw) {
                        sums[o][th][tw] = bias_val;
                    }
                }
            }
            for (int ic = 0; ic < in_channels; ++ic) {
                const float* smem_ic = smem + ic * in_tile_hw;
                for (int kh = 0; kh < kernel_size; ++kh) {
                    #pragma unroll
                    for (int th = 0; th < THREAD_TILE; ++th) {
                        int ih_local = local_h_start + th * stride + kh;
                        const float* srow = smem_ic + ih_local * in_tile_w + local_w_start;
                        for (int kw = 0; kw < kernel_size; ++kw) {
                            float in_vals[THREAD_TILE];
                            #pragma unroll
                            for (int tw = 0; tw < THREAD_TILE; ++tw) {
                                in_vals[tw] = srow[tw * stride + kw];
                            }
                            for (int o = 0; o < oc_count; ++o) {
                                const float* w_ic = wshared + o * wsize + ic * ksq;
                                float wv = w_ic[kh * kernel_size + kw];
                                #pragma unroll
                                for (int tw = 0; tw < THREAD_TILE; ++tw) {
                                    sums[o][th][tw] += in_vals[tw] * wv;
                                }
                            }
                        }
                    }
                }
            }
            for (int o = 0; o < oc_count; ++o) {
                int oc = oc_base + o;
                #pragma unroll
                for (int th = 0; th < THREAD_TILE; ++th) {
                    int oh = oh_base + th;
                    if (oh >= out_h) continue;
                    #pragma unroll
                    for (int tw = 0; tw < THREAD_TILE; ++tw) {
                        int ow = ow_base + tw;
                        if (ow < out_w) {
                            output[((n * out_channels + oc) * out_h + oh) * out_w + ow] = sums[o][th][tw];
                        }
                    }
                }
            }
        }
        __syncthreads();
    }
}
torch::Tensor conv2d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int padding)
{
    const int batch_size = input.size(0);
    const int in_channels = input.size(1);
    const int in_h = input.size(2);
    const int in_w = input.size(3);
    const int out_channels = weight.size(0);
    const int kernel_size = weight.size(2);
    const int out_h = (in_h + 2 * padding - kernel_size) / stride + 1;
    const int out_w = (in_w + 2 * padding - kernel_size) / stride + 1;
    auto output = torch::zeros({batch_size, out_channels, out_h, out_w}, input.options());
    const int in_tile_h = (TILE_H - 1) * stride + kernel_size;
    const int in_tile_w = (TILE_W - 1) * stride + kernel_size;
    dim3 threads(BLOCK_W, BLOCK_H);
    dim3 blocks((out_w + TILE_W - 1) / TILE_W,
                (out_h + TILE_H - 1) / TILE_H,
                batch_size);
    size_t shared_mem_size = (size_t)(in_channels * in_tile_h * in_tile_w + OC_TILE * in_channels * kernel_size * kernel_size) * sizeof(float);
    cudaFuncSetAttribute(conv2d_kernel_tiled, cudaFuncAttributeMaxDynamicSharedMemorySize, (int)shared_mem_size);
    conv2d_kernel_tiled<<<blocks, threads, shared_mem_size>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        in_channels,
        in_h, in_w,
        out_channels,
        out_h, out_w,
        kernel_size,
        stride,
        padding,
        in_tile_h,
        in_tile_w
    );
    return output;
}
"""

conv2d_cpp_source = r"""
torch::Tensor conv2d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int padding);
"""

conv2d_module = load_inline(
    name="conv2d_module",
    cpp_sources=conv2d_cpp_source,
    cuda_sources=conv2d_source,
    functions=["conv2d_cuda"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self, num_classes=1000):
        super(ModelNew, self).__init__()
        self.in_channels = 3
        self.out_channels = 96
        self.kernel_size = 11
        self.stride = 4
        self.padding = 2

        self.weight = nn.Parameter(
            torch.empty(self.out_channels, self.in_channels, self.kernel_size, self.kernel_size)
        )
        self.bias = nn.Parameter(torch.empty(self.out_channels))

        nn.init.kaiming_uniform_(self.weight, a=5 ** 0.5)
        fan_in = self.in_channels * self.kernel_size * self.kernel_size
        bound = 1 / (fan_in ** 0.5)
        nn.init.uniform_(self.bias, -bound, bound)

        self.conv2d = conv2d_module

    def forward(self, x):
        x = x.contiguous().cuda()
        weight = self.weight.contiguous().cuda()
        bias = self.bias.contiguous().cuda()
        return self.conv2d.conv2d_cuda(x, weight, bias, self.stride, self.padding)

